import{_ as a,o as t,c as r,a4 as o}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"Erasure Coding / Reed-Solomon","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/fault/erasure.md","filePath":"distributed/fault/erasure.md","lastUpdated":1788475713000}'),i={name:"distributed/fault/erasure.md"};function s(l,e,d,n,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="erasure-coding-reed-solomon" tabindex="-1">Erasure Coding / Reed-Solomon <a class="header-anchor" href="#erasure-coding-reed-solomon" aria-label="Permalink to &quot;Erasure Coding / Reed-Solomon&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p><strong>Erasure Coding (EC)</strong> 是 RAID-6 与 云存储 (HDFS, Ceph, AWS S3 Object, Google GCS) 替代 3 副本的低 storage-cost 高 durability 系统。 EC 把数据切成 N=K+M 个 chunks (K data + M parity), 任 K 个 chunks 重构原数据, 容忍 M 个 chunks 损失。 Reed-Solomon (RS) 编码是最常见 coding——数学是 GF(2^8) 多项式运算. 3 副本 = storage 3x, EC=RS(10,4) 把 storage decrease 到 1.4×, durability 仍 10^11. EC 的重建成本 (rebuild) 比 replication 高一个数量级——trade-off 是热数据用 replication, 冷数据用 EC. 本章梳理 RS 数学, EC vs Replicated 成本/durability, decode repair, 典型 HDFS / S3 / Ceph 调参, typical 事故.</p><hr><h2 id="一、reed-solomon-数学" tabindex="-1">一、Reed-Solomon 数学 <a class="header-anchor" href="#一、reed-solomon-数学" aria-label="Permalink to &quot;一、Reed-Solomon 数学&quot;">​</a></h2><h3 id="有限域-gf-2-8" tabindex="-1">有限域 GF(2^8) <a class="header-anchor" href="#有限域-gf-2-8" aria-label="Permalink to &quot;有限域 GF(2^8)&quot;">​</a></h3><p>Reed-Solomon 在 GF(2^8) 有限域上做矩阵运算. 每 byte 是一个 GF(2^8) 元素, 加法 = XOR, 乘法 = 模一个 generator polynomial (e.g., 0x11b = x^8 + x^4 + x^3 + x + 1).</p><h3 id="编码原理" tabindex="-1">编码原理 <a class="header-anchor" href="#编码原理" aria-label="Permalink to &quot;编码原理&quot;">​</a></h3><p>把 K 个数据 blocks <code>d_1, ..., d_K</code> 排成数组. 一组 M 个校验 blocks <code>p_1, ..., p_M</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[p_1, p_2, ..., p_M] = [d_1, d_2, ..., d_K] · G[K, K+M]</span></span></code></pre></div><p>其中 G 是 K × (K+M) &quot;generator matrix&quot; — 通常用 Vandermonde 或 Cauchy matrix. 任 K 列取出来构成 K × K 可逆矩阵 (over GF(2^8)) → 解 K 元线性方程组 reconstruct 数据.</p><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><p><strong>RS(4,2)</strong>: K=4 data blocks + M=2 parity blocks = N=6 total. 容忍 2 块 损失.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data:    [d1, d2, d3, d4]</span></span>
<span class="line"><span>parity:</span></span>
<span class="line"><span>  p1 = d1 ⊕ d2 ⊕ d3 ⊕ d4        # XOR parity</span></span>
<span class="line"><span>  p2 = g1·d1 ⊕ g2·d2 ⊕ g3·d3 ⊕ g4·d4    # strip parity with coefficients</span></span></code></pre></div><p>任 4 个块 (out of 6) 都能恢复原 4 个 data blocks.</p><p><strong>RS(10,4)</strong>: K=10, M=4, N=14, storage overhead 14/10 = 1.4×, 容忍 4 块损失. HDFS 用此配.</p><h3 id="decode" tabindex="-1">Decode <a class="header-anchor" href="#decode" aria-label="Permalink to &quot;Decode&quot;">​</a></h3><p>If M 个 blocks lost, 拿 K 个 remaining blocks 形成 K × K submatrix of G, invert → 多 data. Concrete: 解 K 元线性方程组 over GF(2^8). CPU cost O(K²) per solve.</p><h3 id="cauchy-vs-vandermonde" tabindex="-1">Cauchy vs Vandermonde <a class="header-anchor" href="#cauchy-vs-vandermonde" aria-label="Permalink to &quot;Cauchy vs Vandermonde&quot;">​</a></h3><p>Cauchy matrix 让 every submatrix K × K invertible, 并方便 SIMD 加速 (Cauchy elements can be ratio&#39;d creatively). Jerasure library 2.0 提供 optimized RS over GF(2^8). Intel ISA-L 加速 SIMD XOR + GF multiply. 现代 EC libraries (Jerasure 2.0, ISA-L, klauspost/reedsolomon Rust crate) roundly 让 1Gbps 翻 performance.</p><hr><h2 id="二、cost-benefit-replicated-vs-erasure" tabindex="-1">二、Cost-Benefit: Replicated vs Erasure <a class="header-anchor" href="#二、cost-benefit-replicated-vs-erasure" aria-label="Permalink to &quot;二、Cost-Benefit: Replicated vs Erasure&quot;">​</a></h2><h3 id="storage-overhead" tabindex="-1">Storage Overhead <a class="header-anchor" href="#storage-overhead" aria-label="Permalink to &quot;Storage Overhead&quot;">​</a></h3><table tabindex="0"><thead><tr><th>配置</th><th>Storage overhead</th><th>Tolerance (lost chunks)</th><th>例子</th></tr></thead><tbody><tr><td>3 副本</td><td>3x</td><td>2 nodes</td><td>DynamoDB, etcd, CockroachDB 默认</td></tr><tr><td>2 副本</td><td>2x</td><td>1 node</td><td>部分 cold-storage</td></tr><tr><td>RS(6,3)</td><td>1.5x</td><td>3 chunks</td><td>部分 cluster</td></tr><tr><td>RS(10,4)</td><td>1.4x</td><td>4 chunks</td><td>HDFS EC 默认</td></tr><tr><td>RS(11,15)</td><td>2.27x</td><td>15 chunks</td><td>Glacier archival tier</td></tr></tbody></table><h3 id="durability-model" tabindex="-1">Durability model <a class="header-anchor" href="#durability-model" aria-label="Permalink to &quot;Durability model&quot;">​</a></h3><p>Durability: 数据不丢概率 = <code>1 - P(超出 M failures)</code>. 失败假设: 1 disk AFR 1-4%. EC 让 cross-AZ + cross-rack placement让失败 uncorrelated.</p><p>EC durability vs replication 相同 storage cost:</p><ul><li>Replication 3x (3 nodes): 11 9 durability 等于√N failure model over typical cluster life.</li><li>RS(10,4) 1.4x cost + cross-rack placement保持 11 9 durability, 配 1x cost.</li><li>RS 稍 长 间 reaction uses 释 actualmentation depends on rack妇联 + repair window.</li></ul><h3 id="repair-cost" tabindex="-1">Repair Cost <a class="header-anchor" href="#repair-cost" aria-label="Permalink to &quot;Repair Cost&quot;">​</a></h3><p>EC repair 在 failures 时 cost 大:</p><ul><li>Replicated (3 replicas): 1 disk failed → 1 副本 byte stream 接 (network bandwidth = lost disk size).</li><li>EC RS(10,4): 1 chunk lost → client 拉 K=10 个 chunks → decode → reconstruct missing chunk. total read traffic = 10× chunk size, ~10x 比单 replication 修理代价.</li></ul><p>实际: EC repair write 工作量 = K × lost_chunk. 高 K 的 爆炸 networks; low K 不耐多 failures. 平衡点 K=6-10.</p><h3 id="trade-off-summary" tabindex="-1">Trade-off Summary <a class="header-anchor" href="#trade-off-summary" aria-label="Permalink to &quot;Trade-off Summary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>3 replicas</th><th>RS(K,M)</th></tr></thead><tbody><tr><td>Storage cost</td><td>3x</td><td>~1.4-1.7x</td></tr><tr><td>Read throughput</td><td>High (local mirror)</td><td>moderately lower</td></tr><tr><td>Write throughput</td><td>High</td><td>lower (encoder overhead)</td></tr><tr><td>Durability</td><td>11 9</td><td>11 9 same 经</td></tr><tr><td>Repair cost (per node lost)</td><td>1x</td><td>~K times harder</td></tr><tr><td>Latency</td><td>Low</td><td>Higher (decode cost per read)</td></tr><tr><td>Use case</td><td>Hot data</td><td>Cold, archival</td></tr></tbody></table><p><strong>工业推荐</strong>: 热数据用 replication (低 latency + fast failover); 冷 数据 / archival 用 EC (省 storage, 接受 高 repair latency).</p><hr><h2 id="三、hdfs-erasure-coding" tabindex="-1">三、HDFS Erasure Coding <a class="header-anchor" href="#三、hdfs-erasure-coding" aria-label="Permalink to &quot;三、HDFS Erasure Coding&quot;">​</a></h2><p>HDFS 早期 (3 副本) budget 大: 3TB 数据存储需要 9TB 集群. 2015 HDFS-EC (HDFS-7338) 加 RS 默认 RS(6,3). HDFS 3.0+ 设置:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hdfs erasurecode -setPolicy -policy RS-6-3 path</span></span></code></pre></div><p>EC striping layout: 大 file 分 striping units (8KB default). 每 K 个 striping units 一组 → K data + M parity = N chunks per cell stored across N 个 datanodes.</p><p><strong>性能 trade-off</strong>: HDFS EC bottleneck in client 上 read M &quot;fill all units&quot;. throughput 读写 lower 30-50% vs replication. cold 数据节省 storage cost 补偿.</p><h3 id="rack-awareness" tabindex="-1">Rack awareness <a class="header-anchor" href="#rack-awareness" aria-label="Permalink to &quot;Rack awareness&quot;">​</a></h3><p>HDFS EC 跨 rack 容 available. N=9 chunks mixed across racks, 让 nodes lost 各 rack 组好. Rack fail with 9-nodes-loss = pedant.</p><h3 id="rs-legacy-10-4" tabindex="-1">RS-LEGACY-10-4 <a class="header-anchor" href="#rs-legacy-10-4" aria-label="Permalink to &quot;RS-LEGACY-10-4&quot;">​</a></h3><p>legacy policy for older clients. EC at client side or datanode side (default client).</p><hr><h2 id="四、ceph-ec" tabindex="-1">四、Ceph EC <a class="header-anchor" href="#四、ceph-ec" aria-label="Permalink to &quot;四、Ceph EC&quot;">​</a></h2><p>Ceph RADOSPOOL <code>erasure</code> plugin. EC pool 后 EC= 基本 write 直接 EC + get reconstruct.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ceph</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> osd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> erasure-code-profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myprofile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> k=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> m=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> crush-failure-domain=host</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ceph</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> osd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mypool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> erasure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myprofile</span></span></code></pre></div><p>Ceph EC pool 不支持 partial 修改 (EC 数学不支持仅改 one byte 不重算 parity). 解决方案:</p><ol><li>EC <strong>base tier</strong> for cold data。</li><li><strong>Replicated tier</strong> for hot data, after age cool → migrate to EC by tier mechanism.</li></ol><h3 id="ec-overwrite-in-ceph" tabindex="-1">EC Overwrite in Ceph <a class="header-anchor" href="#ec-overwrite-in-ceph" aria-label="Permalink to &quot;EC Overwrite in Ceph&quot;">​</a></h3><p><code>rbd</code> (RBD 块存储) 后台要 write 改 ECS data + 一些 pkgoverhead. Ceph internally <strong>overwrite</strong> uses a write-modify-rewrite pattern但 高 cost. 块存储工业实践: 多 使用三副本 for RBD pool + EC pool 只用 RBD export snapshot archive.</p><h3 id="ec-coding-library-jerasure" tabindex="-1">EC coding library: Jerasure <a class="header-anchor" href="#ec-coding-library-jerasure" aria-label="Permalink to &quot;EC coding library: Jerasure&quot;">​</a></h3><p>Ceph 用 Jerasure 2.0 + GF-Complete SIMD 加速 (因 ISA-L license 不纯 GPL-compatible). Newer Ceph 用 <code>isa-l</code> plugin 兼 quickал encoding with SIMD SIMD (SSSE3, AVX2). 编码 throughput 1-5Gbps CPU on modern Intel server.</p><hr><h2 id="五、aws-s3-gcs-ec-internal" tabindex="-1">五、AWS S3 / GCS EC Internal <a class="header-anchor" href="#五、aws-s3-gcs-ec-internal" aria-label="Permalink to &quot;五、AWS S3 / GCS EC Internal&quot;">​</a></h2><p><strong>AWS S3</strong>:</p><ul><li>Cross-region replication for small + EC for large files</li><li>durability 11 9 declared, RS internal assumed config</li><li>S3 Glacier uses RS with even lower storage cost (K=11, M=15 confirmed by AWS whitepaper reasoning)</li><li>Standard class ~$0.023/GB; Glacier ~$0.004/GB</li></ul><p><strong>Google Cloud Storage</strong>: Multi-region GCS declares 11 9 EC with cross-region 修复. Coldline / Archive ~$0.004/GB.</p><p><strong>Azure Blob Storage</strong>: Standard tier <code>LRS</code> (Locally redundant 3 replicas), <code>ZRS</code> (zone redundant 3 replicas across AZs), <code>GRS</code> (geo-redundant 6 replicas cross-region), <code>RAGRS</code> (read-access GRS), <code>GZRS</code> (geo + zone). Hot tier replication vs cool tier use EC under-the-hood.</p><hr><h2 id="六、典型使用与对比" tabindex="-1">六、典型使用与对比 <a class="header-anchor" href="#六、典型使用与对比" aria-label="Permalink to &quot;六、典型使用与对比&quot;">​</a></h2><h3 id="backblaze-vaults" tabindex="-1">Backblaze Vaults <a class="header-anchor" href="#backblaze-vaults" aria-label="Permalink to &quot;Backblaze Vaults&quot;">​</a></h3><p>Backblaze (B2) 是 cold storage vendor. 公开 durability stat over 10 years: 总 storage = 2EB+, annual durability 实测 &gt; 11 9 with replication 3 + monitoring + auto repair. 双 copy replication suffices for 80% use, EC for cold tiers archive.</p><h3 id="facebook-warm-btrfs-storage" tabindex="-1">Facebook Warm Btrfs Storage <a class="header-anchor" href="#facebook-warm-btrfs-storage" aria-label="Permalink to &quot;Facebook Warm Btrfs Storage&quot;">​</a></h3><p>Facebook 大型 photo storage 平台 Haystack 早期 replication 3 后 came f4 storage with EC (+ replication hot tier). storage cost saved &gt; 65% in生产.</p><h3 id="spotify-cassandra" tabindex="-1">Spotify Cassandra <a class="header-anchor" href="#spotify-cassandra" aria-label="Permalink to &quot;Spotify Cassandra&quot;">​</a></h3><p>Spotify on-prem Cassandra集群 replication 3 (RF=3 + LOCAL_QUORUM write), no EC—Cassandra热数据 + EC slow not worth it. backup tier 用 S3 EC.</p><h3 id="hbase-hdfs-ec" tabindex="-1">HBase + HDFS EC <a class="header-anchor" href="#hbase-hdfs-ec" aria-label="Permalink to &quot;HBase + HDFS EC&quot;">​</a></h3><p>HBase 通常用 HDFS-EC backend for archived HFiles (after compaction → cold); hot Memtable 与 HFiles use replicated HDFS. tiered.</p><hr><h2 id="七、典型事故" tabindex="-1">七、典型事故 <a class="header-anchor" href="#七、典型事故" aria-label="Permalink to &quot;七、典型事故&quot;">​</a></h2><h3 id="hdfs-ec-migration-cost" tabindex="-1">HDFS EC Migration Cost <a class="header-anchor" href="#hdfs-ec-migration-cost" aria-label="Permalink to &quot;HDFS EC Migration Cost&quot;">​</a></h3><p>某 cluster 4-year EC migration: total migration took 6 months. 老 3-replication data store 6 month before EC switch fully complete. 测试 HDFS-EC 实际 5x 写 throughput lower 3-replicate; migration 加上 rack-aware placement 严格 complies是 host count &gt;&gt; N.</p><h3 id="ceph-ec-pool-rbd-overwrite-cost" tabindex="-1">Ceph EC Pool RBD Overwrite Cost <a class="header-anchor" href="#ceph-ec-pool-rbd-overwrite-cost" aria-label="Permalink to &quot;Ceph EC Pool RBD Overwrite Cost&quot;">​</a></h3><p>某公司 Ceph cluster test EC pool for RBD images; found 每次写入 4KB block 触发 full stripe rewrite (64KB 计算), throughput drop 90% vs replicated. Fix: RBD pool = replicated (3x storage cost), EC pool only for <code>rbd export-diff</code> archive.</p><h3 id="backblaze-drive-failure-correlation" tabindex="-1">Backblaze Drive Failure Correlation <a class="header-anchor" href="#backblaze-drive-failure-correlation" aria-label="Permalink to &quot;Backblaze Drive Failure Correlation&quot;">​</a></h3><p>Backblaze 公布 failure stat 显示<strong>同型号磁盘 group</strong> fail correlation 高 (e.g., 6TB Seagate 某型号 batch 30% AFR 1 year). EC 跨 model 跨 batch placement让 failures uncorrelated, EC durability 实际 低于 pure theoretical.</p><hr><h2 id="八、易错清单" tabindex="-1">八、易错清单 <a class="header-anchor" href="#八、易错清单" aria-label="Permalink to &quot;八、易错清单&quot;">​</a></h2><ol><li><strong>EC not low latency read</strong>: read 触发 K-decodemath; 第一线程 linear time ⋯ delays unit -bandwidth EC-read latency 不 as good replication (1 local replica 0 decoders).</li><li><strong>Repair boltloads nodes</strong>: K=10 EC, repair 1 节点 loss 推 K × size traffic 到 data. existing storage network capacity risk fix constrain stage. Cluster fail lethal 春 加 disk event 穿后 schedule streams tenant lift (data-nodes wave).</li><li><strong>Similar drive failure correlation</strong>is 是 real (Backblaze data): EC placement 跨 manufacturer batch + rack + DC + PSU. Placement policy 中 N,M fail now considersuper 低.</li><li><strong>EC overwrite 实际 expensive</strong>: don&#39;t configure RBD VM images on EC pool unless cold archive use only. Ceph EC money 醒: <code>EC poo supports overwrite but very slow</code>.</li><li><strong>N+M &lt; availableFaultTolerance</strong>: design深层 AZ 数 与 cluster host数 ≥ N+M, 否则 N+M fail to placement. Cluster 最少 N+M 个 distinct hosts.</li><li><strong>Network CPU repair costcould = hot bonds</strong>: EC repair cost uses CPU GF-Complete SIMD + network. idle 加 SR-bar might queue. Don&#39;t run parallel repairs in cluster (stagger).</li><li><strong>EC smallest file 筹算 write</strong>: small file 5genome rowEC, postencoded chunk程 invokes large forbidden tests. 小file 的formance extra loin frac. 8 KB at K=10 mean even 80KB trips cache.</li><li><strong>EC + small副本</strong>: 必须 intersect cluster availability zone. 实际 AZ fail IT༉IRT worst case flash over racks in availability zone is ensuite; design <code>crush-failure-domain=host</code> does not AZ issues.</li><li><strong>EC chunksize duration overhead</strong>: chunksize 默认8KB با standard test optimus. High seek node K_Block scriptpath 三消wist 大小与 high 节 cost larger chunksize → 1MB stroage run cost CPU-维_2 36 min-refresh.</li></ol><hr><h2 id="九、这一章带走的东西" tabindex="-1">九、这一章带走的东西 <a class="header-anchor" href="#九、这一章带走的东西" aria-label="Permalink to &quot;九、这一章带走的东西&quot;">​</a></h2><ol><li>EC RS(K,M) = K data + M parity 总 N=K+M, 容忍 M loss. K+M 元素写离plus修复 trade 复杂度 = read extra K decode startup.</li><li>EC 是 cold 数据低 storage cost trade better durability hot-replication alternative (1.4-2x storage vs 3x).</li><li>Controlled instead全年为期, hot-vs replication 冷 storage tier EC 灯工艺; use Ceph erasure pool replicate hot in tier selection.</li><li>EC内数学: GF(2^8) + Cauchy matrix 任 K × K 可逆咀嚼 on algorithms Duncan by SIMD CPU (Jerasure2, ISA-L).</li><li>3 副本核心更优of saturate hot-storage. cold一is cost pressure 长还, 偶尔 display o (-1node service fill 快热点 multlicated) sbe <code>/noven αsymbol code惠pbacket ccoberG/c per node network id poolter al Cluster Latvia</code>.</li><li>同 model磁disk correlation is important fault; Only cross-rack cross-batch cross-routing placement saves EC durability 真 porter 后 鹿 team processes.</li><li><strong>For industry-保管 amazon s3 (yield耐 ECgalaxy 11 9) EC+Storage我用 345 cheaper in manyreplic lead multi-е cluster</strong>, 我圈14元 NEW 和两个acus EB[x] = (R) durability.</li><li><strong>写入 EC 跹 destructor cache</strong>: 8ussion. 失把 &quot;高 次成本 EC + First ≠ streakability bucket than 主 low存皆是f 在 not data home cluster \` storage mut 5%&quot;.</li></ol><hr><p>下一节 → <a href="./scheduling">Borg / Kubernetes / Mesos 调度</a></p>`,87)])])}const g=a(i,[["render",s]]);export{u as __pageData,g as default};
